import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Attribute;
import org.junit.Test;
import static org.junit.Assert.*;

public class SafelistTest {

    @Test
    public void noneTest() {
        Safelist result = Safelist.none();
        assertNotNull(result);
    }

    @Test
    public void simpleTextTest() {
        Safelist result = Safelist.simpleText();
        assertNotNull(result);
    }

    @Test
    public void basicTest() {
        Safelist result = Safelist.basic();
        assertNotNull(result);
    }

    @Test
    public void basicWithImagesTest() {
        Safelist result = Safelist.basicWithImages();
        assertNotNull(result);
    }

    @Test
    public void relaxedTest() {
        Safelist result = Safelist.relaxed();
        assertNotNull(result);
    }

    @Test
    public void addRemoveTagsTest() {
        Safelist safelist = new Safelist();
        safelist.addTags("tag1", "tag2");
        assertTrue(safelist.isSafeTag("tag1"));
        safelist.removeTags("tag1", "tag2");
        assertFalse(safelist.isSafeTag("tag1"));
    }

    @Test
    public void addRemoveAttributesTest() {
        Safelist safelist = new Safelist();
        safelist.addAttributes("tag1", "attr1", "attr2");
        Element element = Mockito.mock(Element.class);
        Attribute attribute = new Attribute("attr1", "value");
        assertTrue(safelist.isSafeAttribute("tag1", element, attribute));
        safelist.removeAttributes("tag1", "attr1", "attr2");
        assertFalse(safelist.isSafeAttribute("tag1", element, attribute));
    }

    @Test
    public void addRemoveEnforcedAttributeTest() {
        Safelist safelist = new Safelist();
        safelist.addEnforcedAttribute("tag1", "attr1", "value1");
        Attributes attrs = safelist.getEnforcedAttributes("tag1");
        assertTrue(attrs.hasKey("attr1"));
        safelist.removeEnforcedAttribute("tag1", "attr1");
        attrs = safelist.getEnforcedAttributes("tag1");
        assertFalse(attrs.hasKey("attr1"));
    }

    @Test
    public void preserveRelativeLinksTest() {
        Safelist safelist = new Safelist();
        safelist.preserveRelativeLinks(true);
    }

    @Test
    public void addRemoveProtocolsTest() {
        Safelist safelist = new Safelist();
        safelist.addProtocols("tag1", "attr1", "https", "http");
    }

    @Test
    public void safelistCopyConstructorTest() {
        Safelist sl = Safelist.none();
        sl.addTags("test");
        Safelist slCopy = new Safelist(sl);
        assertTrue(slCopy.isSafeTag("test"));
    }
}
